window.__ModuleLoader__.load({
  id: 'dsh-running-whale-skin',
  factory() {
    const CSS = "/* dsh-running-whale-skin: light-mode animation for the running status. */\n@media (forced-colors: none) {\n  body:not([data-ds-dark-theme]) [data-chat-running] span[class*=\"runningWhaleAnimated\"] {\n    -webkit-mask: none;\n    mask: none;\n    background: url(\"data:image/gif;base64,\") center / contain no-repeat;\n  }\n}";
    return {
      apply(ctx) {
        ctx.effect(() => {
          const style = document.createElement('style');
          style.dataset.plugin = 'dsh-running-whale-skin';
          style.textContent = CSS;
          document.head.append(style);
          return () => style.remove();
        }, 'running-whale-skin: styles');
      },
    };
  },
});
